-- CivicFlow schema reference. The web installer creates tables and seed records automatically.
-- Use a NEW empty database. Do not import this file before running the web installer.
CREATE TABLE IF NOT EXISTS departments (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(140) NOT NULL, code VARCHAR(20) NOT NULL UNIQUE, description TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS services (id INTEGER PRIMARY KEY AUTO_INCREMENT, department_id INTEGER NOT NULL, title VARCHAR(180) NOT NULL, slug VARCHAR(100) NOT NULL UNIQUE, kind VARCHAR(20) NOT NULL, description TEXT NOT NULL, requirements TEXT NOT NULL, fee DECIMAL(12,2) NOT NULL DEFAULT 0, sla_hours INTEGER NOT NULL DEFAULT 72, active INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(department_id) REFERENCES departments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS roles (role_key VARCHAR(50) PRIMARY KEY, role_name VARCHAR(100) NOT NULL, description TEXT NOT NULL, is_system INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS role_permissions (role_key VARCHAR(50) NOT NULL, permission_key VARCHAR(100) NOT NULL, PRIMARY KEY(role_key,permission_key), FOREIGN KEY(role_key) REFERENCES roles(role_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(140) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(25) NOT NULL DEFAULT '', password_hash VARCHAR(255) NOT NULL, role VARCHAR(50) NOT NULL DEFAULT 'citizen', department_id INTEGER NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', email_verified_at DATETIME NULL, notify_email INTEGER NOT NULL DEFAULT 1, notify_sms INTEGER NOT NULL DEFAULT 0, auth_version INTEGER NOT NULL DEFAULT 1, totp_secret TEXT NULL, totp_confirmed INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, FOREIGN KEY(department_id) REFERENCES departments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS user_roles (user_id INTEGER NOT NULL, role_key VARCHAR(50) NOT NULL, PRIMARY KEY(user_id,role_key), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_key) REFERENCES roles(role_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS email_templates (id INTEGER PRIMARY KEY AUTO_INCREMENT, template_key VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(140) NOT NULL, subject VARCHAR(180) NOT NULL, html_body TEXT NOT NULL, plain_body TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS device_sessions (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, ip_address VARCHAR(64) NOT NULL, user_agent VARCHAR(250) NOT NULL, created_at DATETIME NOT NULL, last_seen DATETIME NOT NULL, revoked_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS recovery_codes (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, code_hash VARCHAR(64) NOT NULL UNIQUE, used_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS requests (id INTEGER PRIMARY KEY AUTO_INCREMENT, reference VARCHAR(50) NOT NULL UNIQUE, access_token VARCHAR(64) NOT NULL, user_id INTEGER NOT NULL, service_id INTEGER NOT NULL, department_id INTEGER NOT NULL, assigned_to INTEGER NULL, kind VARCHAR(20) NOT NULL, subject VARCHAR(180) NOT NULL, description TEXT NOT NULL, location VARCHAR(200) NOT NULL DEFAULT '', state_name VARCHAR(60) NOT NULL DEFAULT '', organisation VARCHAR(180) NOT NULL DEFAULT '', priority VARCHAR(20) NOT NULL DEFAULT 'normal', status VARCHAR(30) NOT NULL, due_at DATETIME NULL, escalated_at DATETIME NULL, closed_at DATETIME NULL, version INTEGER NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(service_id) REFERENCES services(id), FOREIGN KEY(department_id) REFERENCES departments(id), FOREIGN KEY(assigned_to) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTO_INCREMENT, request_id INTEGER NOT NULL, actor_id INTEGER NULL, from_status VARCHAR(30) NOT NULL DEFAULT '', to_status VARCHAR(30) NOT NULL DEFAULT '', message TEXT NOT NULL, visibility VARCHAR(20) NOT NULL DEFAULT 'public', created_at DATETIME NOT NULL, FOREIGN KEY(request_id) REFERENCES requests(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS attachments (id INTEGER PRIMARY KEY AUTO_INCREMENT, request_id INTEGER NOT NULL, user_id INTEGER NOT NULL, original_name VARCHAR(200) NOT NULL, stored_name VARCHAR(100) NOT NULL UNIQUE, mime VARCHAR(100) NOT NULL, size_bytes INTEGER NOT NULL, sha256 VARCHAR(64) NOT NULL, visibility VARCHAR(20) NOT NULL DEFAULT 'public', created_at DATETIME NOT NULL, FOREIGN KEY(request_id) REFERENCES requests(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, request_id INTEGER NULL, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, link VARCHAR(250) NOT NULL, read_at DATETIME NULL, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS outbox (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, request_id INTEGER NULL, channel VARCHAR(15) NOT NULL, recipient VARCHAR(190) NOT NULL, subject VARCHAR(180) NOT NULL, body TEXT NOT NULL, html_body TEXT NULL, template_key VARCHAR(60) NULL, state VARCHAR(30) NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at DATETIME NULL, sent_at DATETIME NULL, last_error VARCHAR(250) NOT NULL DEFAULT '', provider_id VARCHAR(150) NOT NULL DEFAULT '', created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS password_resets (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS email_verifications (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTO_INCREMENT, actor_id INTEGER NULL, action VARCHAR(100) NOT NULL, entity_id INTEGER NULL, metadata TEXT NOT NULL, ip_address VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS feedback (id INTEGER PRIMARY KEY AUTO_INCREMENT, request_id INTEGER NOT NULL UNIQUE, user_id INTEGER NOT NULL, rating INTEGER NOT NULL, comment TEXT NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(request_id) REFERENCES requests(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS faqs (id INTEGER PRIMARY KEY AUTO_INCREMENT, question VARCHAR(220) NOT NULL, answer TEXT NOT NULL, keywords VARCHAR(250) NOT NULL, active INTEGER NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS announcements (id INTEGER PRIMARY KEY AUTO_INCREMENT, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_requests_user ON requests(user_id);
CREATE INDEX idx_requests_dept_status ON requests(department_id,status);
CREATE INDEX idx_requests_due ON requests(status,due_at);
CREATE INDEX idx_events_request ON events(request_id);
CREATE INDEX idx_notifications_user ON notifications(user_id,read_at);
CREATE INDEX idx_outbox_state ON outbox(state,next_attempt_at);
CREATE INDEX idx_audit_date ON audit_logs(created_at);
